use b27_primitives::{compress,decompress,stream,cvnss};
fn main(){let mut s=0x12345678u32;let mut next=||{s=s.wrapping_mul(1664525).wrapping_add(1013904223);(s>>24)as u8};let raw="tiếng việt oà òa 😀".as_bytes();let corpus:Vec<_>=(0..10).map(|m|compress(raw,m).unwrap()).collect();let mut framed=Vec::new();stream::encode(raw,&mut framed,6).unwrap();let mut legacy=b"B27F".to_vec();legacy.extend_from_slice(&corpus[0][4..]);let mut counts=[0u64;14];for i in 0..1_000_000usize{let target=i%14;counts[target]+=1;if target<10||target==10{let mut b=if target==10{legacy.clone()}else{corpus[target].clone()};let p=next()as usize%b.len();b[p]^=next();if b.len()>=9{b[5]=0;b[6]=0;}if i%7==0{b.truncate(b.len()/2)}let _=decompress(&b);}else if target==11{let mut b=framed.clone();let p=next()as usize%b.len();b[p]^=next();let _=stream::decode_strict(&b[..],std::io::sink(),4096);}else if target==12{let n=(next()%128)as usize;let b:Vec<_>=(0..n).map(|_|next()).collect();let _=decompress(&b);let _=cvnss::api_json(&b);}else{let n=(next()%64)as usize;let b:Vec<_>=(0..n).map(|_|next()).collect();let mode=(i/14%10)as u8;assert_eq!(decompress(&compress(&b,mode).unwrap()).unwrap(),b);}}println!("{}",serde_json::json!({"seed":305419896,"cases":1000000,"counts":counts,"completed":true}));}
